create extension if not exists pgcrypto;
do $$ begin create type hms_role as enum ('admin','reception','doctor','lab','pharmacy','patient'); exception when duplicate_object then null; end $$;
create table if not exists hospitals(id uuid primary key default gen_random_uuid(),name text not null,code text not null unique,created_at timestamptz not null default now());
create table if not exists users(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,email text not null,full_name text not null,role hms_role not null,password_hash text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(hospital_id,email));
alter table users add column if not exists must_change_password boolean not null default true;alter table users add column if not exists last_login_at timestamptz;alter table users add column if not exists password_changed_at timestamptz not null default now();alter table users add column if not exists updated_at timestamptz not null default now();
create table if not exists patients(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,uhid text not null,full_name text not null,mobile text,gender text,date_of_birth date,blood_group text,address text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(hospital_id,uhid));
create table if not exists patient_assignments(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,patient_id uuid not null references patients(id) on delete cascade,doctor_user_id uuid not null references users(id),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists lab_reports(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,patient_id uuid not null references patients(id) on delete cascade,report_type text not null,report_name text not null,file_url text,notes text,status text not null default 'ready',uploaded_by uuid not null references users(id),created_at timestamptz not null default now());
create table if not exists doctor_queue(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,patient_id uuid not null references patients(id) on delete cascade,doctor_user_id uuid not null references users(id),status text not null default 'waiting',checked_in_at timestamptz not null default now(),called_at timestamptz);
create table if not exists clinical_notes(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,patient_id uuid not null references patients(id) on delete cascade,doctor_user_id uuid not null references users(id),summary text not null,created_at timestamptz not null default now());
create table if not exists appointments(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,patient_id uuid not null references patients(id) on delete cascade,doctor_user_id uuid references users(id),scheduled_at timestamptz not null,status text not null default 'scheduled',created_at timestamptz not null default now());
create table if not exists prescriptions(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,patient_id uuid not null references patients(id) on delete cascade,doctor_user_id uuid not null references users(id),status text not null default 'pending',created_at timestamptz not null default now(),dispensed_at timestamptz);
create table if not exists prescription_items(id uuid primary key default gen_random_uuid(),prescription_id uuid not null references prescriptions(id) on delete cascade,medicine_name text not null,dose text,frequency text,duration text,quantity text,instructions text);
create index if not exists idx_users_email on users(lower(email));create index if not exists idx_patients_uhid on patients(uhid);create index if not exists idx_assignments_doctor on patient_assignments(doctor_user_id,active);create index if not exists idx_lab_reports_patient on lab_reports(patient_id,created_at desc);create index if not exists idx_doctor_queue_fifo on doctor_queue(doctor_user_id,status,checked_in_at);create index if not exists idx_clinical_notes_patient on clinical_notes(patient_id,created_at desc);create index if not exists idx_appointments_patient on appointments(patient_id,scheduled_at desc);create index if not exists idx_prescriptions_patient on prescriptions(patient_id,created_at desc);

alter table hospitals add column if not exists logo_url text;
alter table hospitals add column if not exists sidebar_color text not null default '#09090a';
alter table hospitals add column if not exists accent_color text not null default '#8a0303';
alter table hospitals add column if not exists background_color text not null default '#f5f5f4';
alter table hospitals add column if not exists updated_at timestamptz not null default now();
